namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple and delicious pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes evenly.", "Add torn mozzarella pieces.", "Bake 10-12 minutes until crust is golden.", "Top with fresh basil and drizzle olive oil."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a creamy spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté onions, garlic, and ginger.", "Add tomato puree and spices, simmer 15 min.", "Stir in cream, add chicken, simmer 10 min.", "Serve with basmati rice or naan."],
            AverageRating = 4.8, RatingCount = 24
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 min.", "Warm tortillas in a dry pan.", "Assemble tacos with beef and toppings.", "Serve with salsa and sour cream."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 4, Title = "Pad Thai", Category = "Asian",
            Description = "Classic Thai stir-fried noodles with shrimp and peanuts.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps = ["Soak rice noodles in warm water 30 min.", "Make sauce: mix tamarind paste, fish sauce, sugar.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the same pan.", "Add noodles and sauce, toss until coated.", "Add shrimp, sprouts, peanuts. Serve with lime."],
            AverageRating = 4.6, RatingCount = 15
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F. Butter ramekins and dust with cocoa.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into ramekins, bake 12-14 minutes.", "Invert onto plates and serve immediately."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 6, Title = "Caesar Salad", Category = "Salads",
            Description = "Crisp romaine lettuce with homemade Caesar dressing.",
            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Anchovy fillets", "Garlic", "Lemon juice", "Dijon mustard", "Olive oil", "Egg yolk"],
            Steps = ["Wash and chop romaine lettuce.", "Make dressing: blend anchovy, garlic, lemon, mustard, egg yolk, and oil.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons.", "Season with black pepper and serve."],
            AverageRating = 4.1, RatingCount = 6
        }
    ];

    private int _nextId = 7;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(string title, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = "Community",
            Description = "A community-submitted recipe.",
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };
        _recipes.Add(recipe);
    }
}

